sys_ux_data_broker_transform.script:
function transform(input) {
    var sysPropertyName = "sam.foundation.current.costcenter.kpi";

    // Fetch the sys_property containing query conditions
    var sysPropertyGR = new GlideRecord('sys_properties');
    sysPropertyGR.addQuery('name', sysPropertyName);
    sysPropertyGR.query();

    if (!sysPropertyGR.next()) {
        gs.log("Error: sys_property '" + sysPropertyName + "' not found.");
        return [[{
            "data": [{
                "value": "0",
                "change": "0",
                "changePercent": "0"
            }],
            "metadata": {
                "eventData": {
                    "indicatorSysid": "fb007202d7130100b96d45a3ce6103b4"
                },
                "previousScoreDate": "1642809600000",
                "dataSourceLabel": "Cost Center Data Quality",
                "changeArrow": "steady",
                "scoreDate": "1642896000000",
                "filterQuery": "",
                "aggregate": {
                    "fieldType": "decimal"
                },
                "format": {
                    "unitFormat": "{0}",
                    "frequency": "daily",
                    "precision": 0
                }
            },
            "sparkline": {
                "data": [
                    {
                        "timestamp": "1637798400000",
                        "value": "0"
                    },
                    {
                        "timestamp": "1642896000000",
                        "value": "0"
                    }
                ],
                "metadata": {
                    "eventData": {
                        "indicatorSysid": "fb007202d7130100b96d45a3ce6103b4"
                    },
                    "dataSourceLabel": "Cost Center Data Quality",
                    "series": [
                        {
                            "label": "Cost Center Data Quality",
                            "id": "value",
                            "type": "value"
                        }
                    ],
                    "aggregate": {
                        "fieldType": "decimal"
                    },
                    "format": {
                        "unitFormat": "{0}",
                        "frequency": "daily",
                        "precision": 0
                    }
                }
            }
        }]];
    }

    // Parse the JSON value from sys_property
    var propertyValue = sysPropertyGR.getValue('value');
    var conditionsArray = JSON.parse(propertyValue); // Convert JSON string to an array

    var totalUsersGR = new GlideRecord('sys_user');
    totalUsersGR.addQuery('active', 'true'); // Ensuring only active users are counted
    totalUsersGR.query();
    var totalCount = totalUsersGR.getRowCount(); // Accurately get the total count

    var inaccurateUserIDs = {}; // Object to track unique user IDs

    for (var i = 0; i < conditionsArray.length; i++) {
        var condition = conditionsArray[i].field; // Extract the field condition

        var inaccurateUsers = new GlideRecord(conditionsArray[i].table); // Use table dynamically
        inaccurateUsers.addEncodedQuery(condition);
        inaccurateUsers.query();

        while (inaccurateUsers.next()) {
            inaccurateUserIDs[inaccurateUsers.getUniqueValue()] = true; // Store unique users
        }
    }

    var inaccurateCount = Object.keys(inaccurateUserIDs).length; // Count unique keys
    var inaccuracyPercentage = totalCount > 0 ? (inaccurateCount / totalCount) * 100 : 0;

    // Format the result according to the expected schema
    return [[{
        "data": [{
            "value": inaccuracyPercentage.toFixed(2),
            "change": "0",
            "changePercent": "0"
        }],
        "metadata": {
            "eventData": {
                "indicatorSysid": "fb007202d7130100b96d45a3ce6103b4"
            },
            "previousScoreDate": "1642809600000",
            "dataSourceLabel": "Cost Center Data Quality",
            "changeArrow": "steady",
            "scoreDate": "1642896000000",
            "filterQuery": "",
            "aggregate": {
                "fieldType": "decimal"
            },
            "format": {
                "unitFormat": "{0}",
                "frequency": "daily",
                "precision": 0
            }
        },
        "sparkline": {
            "data": [
                {
                    "timestamp": "1637798400000",
                    "value": inaccuracyPercentage.toFixed(2)
                },
                {
                    "timestamp": "1642896000000",
                    "value": inaccuracyPercentage.toFixed(2)
                }
            ],
            "metadata": {
                "eventData": {
                    "indicatorSysid": "fb007202d7130100b96d45a3ce6103b4"
                },
                "dataSourceLabel": "Cost Center Data Quality",
                "series": [
                    {
                        "label": "Cost Center Data Quality",
                        "id": "value",
                        "type": "value"
                    }
                ],
                "aggregate": {
                    "fieldType": "decimal"
                },
                "format": {
                    "unitFormat": "{0}",
                    "frequency": "daily",
                    "precision": 0
                }
            }
        }
    }]];
}
